<script setup>
import { reactive, ref, computed, watch, onMounted } from 'vue';
import { api } from '../../services/auth.js';
import ReviewIcon from './ReviewIcon.vue';
const form=reactive({base_url:'',model_name:'',api_key:'',max_retries:3}), loading=ref(false), saving=ref(false), testing=ref(false), result=ref(null), error=ref(''), notice=ref('');
const history=ref([]), historyLoading=ref(false), historyError=ref(''), page=ref(1), total=ref(0), restoring=ref(false), confirmRestore=ref(null), modelForm=ref(null);
const pages=computed(()=>Math.max(1,Math.ceil(total.value/5)));
function apply(data){Object.assign(form,{api_key:''},data);}
async function load(){loading.value=true;error.value='';try{apply(await api('/api/admin/model'));}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function loadHistory(){historyLoading.value=true;historyError.value='';try{const data=await api('/api/admin/model/history?page='+page.value+'&page_size=5');history.value=data.items;total.value=data.total;}catch(e){historyError.value=e.message;}finally{historyLoading.value=false;}}
async function save(){saving.value=true;error.value='';notice.value='';try{apply(await api('/api/admin/model','PUT',{...form}));notice.value='配置已保存';page.value=1;await loadHistory();}catch(e){error.value=e.message;}finally{saving.value=false;}}
async function test(){if(!modelForm.value.reportValidity())return;testing.value=true;result.value=null;error.value='';try{result.value=await api('/api/admin/model/test','POST',{...form});}catch(e){result.value={success:false,message:e.message};}finally{testing.value=false;}}
async function restore(){restoring.value=true;error.value='';try{apply(await api('/api/admin/model/history/'+confirmRestore.value.id+'/restore','POST'));confirmRestore.value=null;result.value=null;notice.value='历史配置已恢复并生效';page.value=1;await loadHistory();}catch(e){error.value=e.message;}finally{restoring.value=false;}}
function go(next){if(next<1||next>pages.value||historyLoading.value)return;page.value=next;loadHistory();}
function date(value){return new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});}
watch(()=>[form.base_url,form.model_name,form.api_key],()=>{result.value=null;});
onMounted(()=>{load();loadHistory();});
</script>
<template>
<div class="model-settings-workspace">
  <p v-if="error" class="admin-message error" role="alert">{{ error }}</p><p v-if="notice" class="admin-message success" role="status">{{ notice }}</p>
  <form ref="modelForm" class="admin-model-panel" @submit.prevent="save"><div class="admin-model-description"><span class="model-service-icon"><ReviewIcon name="sparkles"/></span><h2>模型连接</h2><p>配置兼容 OpenAI 协议的服务，供合同审查、核验与起草使用。</p><span class="model-protocol">OpenAI Compatible</span></div><fieldset class="admin-model-fields" :disabled="loading||saving||testing||restoring"><label>服务地址<input class="field" v-model="form.base_url" type="url" required placeholder="https://api.example.com/v1"><small>模型服务的 API 基础地址</small></label><label>模型名称<input class="field" v-model="form.model_name" required maxlength="200" placeholder="输入模型标识"></label><label>API 密钥 <span v-if="form.has_api_key" class="key-configured">已配置</span><input class="field" v-model="form.api_key" type="password" autocomplete="new-password" :placeholder="form.has_api_key?'留空保留已有密钥':'输入 API Key'"><small>密钥加密保存，留空时保留原有配置</small></label><label>失败重试次数<input class="field admin-retries" v-model.number="form.max_retries" type="number" min="0" max="10" required><small>请求失败后自动重试，支持 0–10 次</small></label>
  <div v-if="result" class="model-test-result" :class="{failed:!result.success}" role="status"><ReviewIcon :name="result.success?'check':'info'"/><span>{{ result.message }}</span><small v-if="result.latency_ms!==undefined">{{ (result.latency_ms/1000).toFixed(2) }} 秒</small></div>
  <div class="admin-model-footer model-settings-actions"><span>测试当前填写的配置，无需先保存</span><button type="button" class="button" @click="test"><ReviewIcon :name="testing?'settings':'validations'"/>{{ testing?'测试中…':'测试连接' }}</button><button class="button primary"><ReviewIcon name="save"/>{{ saving?'保存中…':'保存配置' }}</button></div></fieldset></form>
  <section class="model-history-panel" aria-label="配置历史"><header><div><h2><ReviewIcon name="records"/>配置历史 <span>{{ total }}</span></h2><p>每次保存自动记录，可恢复对应版本及密钥。</p></div><button type="button" class="button" :disabled="historyLoading" @click="loadHistory">刷新</button></header>
  <p v-if="historyError" class="admin-message error" role="alert">{{ historyError }}</p>
  <div class="model-history-scroll"><table class="model-history-table"><thead><tr><th>保存时间</th><th>模型 / 服务地址</th><th>操作人</th><th>操作类型</th><th>密钥</th><th>操作</th></tr></thead><tbody><tr v-for="item in history" :key="item.id"><td>{{ date(item.created) }}</td><td><strong>{{ item.model_name }}</strong><small>{{ item.base_url }}</small></td><td>{{ item.operator }}</td><td>{{ {save:'保存配置',restore:'恢复历史',baseline:'原有配置'}[item.action]||item.action }}</td><td><span :class="{'key-configured':item.has_api_key}">{{ item.has_api_key?'已加密':'环境配置' }}</span></td><td><button type="button" class="model-restore" :disabled="saving||testing||restoring||loading" @click="confirmRestore=item;error=''">恢复此配置</button></td></tr><tr v-if="!history.length"><td colspan="6" class="model-history-empty">{{ historyLoading?'正在读取历史…':'暂无历史，保存配置后将在这里记录' }}</td></tr></tbody></table></div>
  <nav class="admin-pagination" aria-label="配置历史分页"><span>共 {{ total }} 条 · 每页 5 条</span><div><button :disabled="page<=1||historyLoading" @click="go(page-1)" aria-label="历史上一页">‹</button><span class="admin-page-number">{{ page }}</span><span>/ {{ pages }}</span><button :disabled="page>=pages||historyLoading" @click="go(page+1)" aria-label="历史下一页">›</button></div></nav>
  </section>
  <div v-if="confirmRestore" class="model-restore-confirm" role="alertdialog" aria-modal="true" aria-label="确认恢复历史配置" @keydown.esc="!restoring&&(confirmRestore=null)"><section><h2>恢复历史配置</h2><p v-if="error" class="admin-message error" role="alert">{{ error }}</p><p>将恢复 {{ date(confirmRestore.created) }} 保存的「{{ confirmRestore.model_name }}」，包括当时的密钥。当前未保存的修改将被替换。</p><small>恢复后立即生效，并生成一条新的历史记录。</small><div><button class="button" :disabled="restoring" @click="confirmRestore=null">取消</button><button class="button primary" :disabled="restoring" @click="restore">{{ restoring?'恢复中…':'确认恢复' }}</button></div></section></div>
</div>
</template>
<style scoped>
.model-settings-workspace{max-width:1060px}.admin-model-fields{border:0;margin:0;min-width:0}.admin-model-fields:disabled{opacity:.75}.model-settings-actions{gap:10px;align-items:center}.model-settings-actions>span{margin-right:auto;font-size:11px;color:#96a2b4}.model-settings-actions .button{white-space:nowrap}.model-test-result{display:flex;align-items:center;gap:9px;background:#eff8f3;color:#388369;border:1px solid #dfefe5;border-radius:7px;padding:12px;font-size:12px}.model-test-result.failed{background:#fff5f3;color:#b65b56;border-color:#f3e1dd}.model-test-result small{margin-left:auto;white-space:nowrap}.model-history-panel{background:#fff;border:1px solid #e1e6ed;border-radius:11px;margin-top:24px;overflow:hidden}.model-history-panel>header{display:flex;align-items:center;justify-content:space-between;padding:22px 24px;border-bottom:1px solid #e9edf3}.model-history-panel h2{display:flex;align-items:center;gap:9px;font-size:15px;font-weight:600;margin:0}.model-history-panel h2 svg{color:#8195b2}.model-history-panel h2 span{font-size:11px;color:#94a3b8;background:#f1f5fa;border-radius:4px;padding:2px 6px}.model-history-panel header p{font-size:11px;color:#96a2b4;margin:8px 0 0}.model-history-panel header .button{font-weight:400;box-shadow:none}.model-history-scroll{overflow:auto}.model-history-table{width:100%;border-collapse:collapse;min-width:740px;text-align:left}.model-history-table th{background:#f8fafc;color:#929eae;font-size:11px;font-weight:400;padding:12px 20px}.model-history-table td{border-bottom:1px solid #edf1f6;padding:16px 20px;font-size:12px;color:#8391a5}.model-history-table strong{display:block;font-weight:500;color:#425c7f;margin-bottom:5px}.model-history-table small{display:block;font-size:10px;color:#9ca8b8;max-width:230px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.model-history-table th:last-child,.model-history-table td:last-child{text-align:right}.model-restore{padding:4px 0;border:0;background:none;color:#4a70ab;font-size:12px;white-space:nowrap;cursor:pointer}.model-restore:disabled{color:#b4bfce}.model-history-table .model-history-empty{text-align:center;padding:35px}.model-history-panel>.admin-message{margin:15px}.model-restore-confirm{position:fixed;inset:0;z-index:110;display:grid;place-items:center;padding:24px;background:#13243f66;backdrop-filter:blur(3px)}.model-restore-confirm>section{width:440px;max-width:100%;padding:26px;border-radius:12px;background:#fff;box-shadow:0 20px 70px #11213c33}.model-restore-confirm h2{font-size:18px;margin:0 0 18px;font-weight:600}.model-restore-confirm p{font-size:13px;line-height:1.9;color:#64768e}.model-restore-confirm small{font-size:11px;color:#97a3b4}.model-restore-confirm section>div{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}@media(max-width:750px){.model-settings-actions{flex-wrap:wrap}.model-settings-actions>span{width:100%;margin-bottom:7px}.model-history-panel>header{padding:20px}.model-history-table td,.model-history-table th{padding:14px}}
</style>
